ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'output/pdf'; OUT.mkdir(parents=True,exist_ok=True)
SHOTS=ROOT/'tmp/pdfs/screenshots'
pages=[]
def img(name,caption):
    p=SHOTS/name
    if not p.exists(): return '<p class="note">ไม่ได้บันทึกภาพส่วนนี้ในการตรวจครั้งนี้</p>'
    data=base64.b64encode(p.read_bytes()).decode()
    return f'<figure><img src="data:image/png;base64,{data}"><figcaption>{caption}</figcaption></figure>'
def page(title,body,kicker='คู่มือการใช้งาน'):
    pages.append(f'<section><header>PERSONAL TUTOR <span>เอกสารระบบและคู่มือการใช้งาน</span></header><div class="kicker">{kicker}</div><h1>{title}</h1>{body}<footer>Personal Tutor • 5 ตุลาคม 2569 <span>{len(pages)+1}</span></footer></section>')
def steps(items): return '<ol>'+''.join(f'<li>{s}</li>' for s in items)+'</ol>'
def bullets(items): return '<ul>'+''.join(f'<li>{s}</li>' for s in items)+'</ul>'

