with sync_playwright() as p:
    browser=p.chromium.launch(channel='msedge',headless=True)
    tab=browser.new_page(); tab.goto(html_path.as_uri()); tab.evaluate('document.fonts.ready')
    overflow=tab.evaluate('''() => [...document.querySelectorAll('section')].map((s,i)=>({page:i+1, contentBottom:Math.max(...[...s.children].filter(c=>c.tagName!=='FOOTER').map(c=>c.getBoundingClientRect().bottom))-s.getBoundingClientRect().top,footerTop:s.querySelector('footer').getBoundingClientRect().top-s.getBoundingClientRect().top})).filter(x=>x.contentBottom>x.footerTop-8)''')
    print('OVERFLOW',overflow)
    if overflow: raise RuntimeError('Page content overlaps footer')
    tab.pdf(path=str(OUT/'Personal_Tutor_User_Manual_TH.pdf'),format='A4',print_background=True,prefer_css_page_size=True)
    browser.close()
